CREATE TABLE "filamento" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz,
  "active" boolean NOT NULL DEFAULT true,
  "deleted" boolean NOT NULL DEFAULT false,
  "material_id" int NOT NULL,
  "cor" varchar NOT NULL,
  "preco_kg" numeric(5,2) NOT NULL
);

CREATE TABLE "material" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz,
  "active" boolean NOT NULL DEFAULT true,
  "deleted" boolean NOT NULL DEFAULT false,
  "nome" varchar UNIQUE NOT NULL,
  "potencia_media_w" numeric(6,2) NOT NULL
);

CREATE UNIQUE INDEX "uq_material_cor" ON "filamento" ("material_id", "cor");

ALTER TABLE "filamento" ADD FOREIGN KEY ("material_id") REFERENCES "material" ("id") DEFERRABLE INITIALLY IMMEDIATE;
